INSERT INTO jobs (id, company_id, category_id, location_id, title, description, requirements, experience_level, job_type, status, salary_min, salary_max, work_location, expires_at, created_by, created_at, updated_at) VALUES
    ('d0000000-0000-4000-8000-000000000001', '11111111-1111-4111-8111-111111111111', '4b852ce4-a695-417d-8802-237e0ff6279d', '0baec7e5-7a8c-4462-96e6-29a694e0f9e2', 'Java Backend Developer (FRESHER) #1', 'Cơ hội gia nhập Công ty Cổ phần Rikkeisoft ở vị trí Java Backend Developer (FRESHER) #1. Tham gia phát triển các hệ thống quy mô lớn, môi trường Agile chuyên nghiệp, hỗ trợ đào tạo và thưởng dự án hấp dẫn.', 'Thành thạo JAVA_CORE, SPRING_BOOT, SQL. Cấp độ mong muốn: FRESHER. Tư duy giải quyết vấn đề tốt và chủ động trong công việc.', 'FRESHER', 'FULL_TIME', 'APPROVED', 12000000, 18000000, 'Cầu Giấy, Hà Nội', NOW() + interval '20 days', '5326dd94-3eef-481a-ab1c-1067d9697875', NOW() - interval '30 days', NOW()),
    ('d0000000-0000-4000-8000-000000000002', '22222222-2222-4222-8222-222222222222', '9a26a1e2-b29e-462f-9920-b112666b929a', '987d1869-6468-4314-8c71-988926f886cb', 'Frontend React Developer (JUNIOR) #2', 'Cơ hội gia nhập Rikkei Digital Solutions ở vị trí Frontend React Developer (JUNIOR) #2. Tham gia phát triển các hệ thống quy mô lớn, môi trường Agile chuyên nghiệp, hỗ trợ đào tạo và thưởng dự án hấp dẫn.', 'Thành thạo REACT, TYPESCRIPT, JAVASCRIPT. Cấp độ mong muốn: JUNIOR. Tư duy giải quyết vấn đề tốt và chủ động trong công việc.', 'JUNIOR', 'FULL_TIME', 'APPROVED', 18000000, 26000000, 'Nam Từ Liêm, Hà Nội', NOW() + interval '21 days', 'f4c530f6-3b46-4e5d-b4db-ce699cd3db25', NOW() - interval '29 days', NOW()),
    ('d0000000-0000-4000-8000-000000000003', '33333333-3333-4333-8333-333333333333', 'a1f07f52-d6f4-4b1f-8d5c-c310b9966298', '27f18ac1-3f27-475f-9dd1-b7c25c5edb3f', 'Fullstack Software Engineer (MIDDLE) #3', 'Cơ hội gia nhập FPT Software Enterprise ở vị trí Fullstack Software Engineer (MIDDLE) #3. Tham gia phát triển các hệ thống quy mô lớn, môi trường Agile chuyên nghiệp, hỗ trợ đào tạo và thưởng dự án hấp dẫn.', 'Thành thạo JAVA_CORE, SPRING_BOOT, REACT. Cấp độ mong muốn: MIDDLE. Tư duy giải quyết vấn đề tốt và chủ động trong công việc.', 'MIDDLE', 'FULL_TIME', 'APPROVED', 28000000, 43000000, 'Thanh Xuân, Hà Nội', NOW() + interval '22 days', '3a69019f-9dbf-468e-be8c-d59b845ca555', NOW() - interval '28 days', NOW()),
    ('d0000000-0000-4000-8000-000000000004', '44444444-4444-4444-8444-444444444444', '99209648-9626-48ba-81f6-d3aadac13658', 'c1ce8b9f-2d4b-48aa-8443-25827d36d9ff', 'AI & Data Engineer (SENIOR) #4', 'Cơ hội gia nhập Viettel Solutions Technology ở vị trí AI & Data Engineer (SENIOR) #4. Tham gia phát triển các hệ thống quy mô lớn, môi trường Agile chuyên nghiệp, hỗ trợ đào tạo và thưởng dự án hấp dẫn.', 'Thành thạo PYTHON, MACHINE_LEARNING, DATA_ANALYSIS. Cấp độ mong muốn: SENIOR. Tư duy giải quyết vấn đề tốt và chủ động trong công việc.', 'SENIOR', 'INTERNSHIP', 'APPROVED', 42000000, 57000000, 'Đống Đa, Hà Nội', NOW() + interval '23 days', '1f176cc2-057b-4cc0-ab0e-f35a31fd3bee', NOW() - interval '27 days', NOW()),
