-- =============================================================================
-- 03_seed_job_db.sql : JOB SERVICE SEED DATA (job_db)
-- 10 Companies (khớp UUID company_id trong clean_and_sync_users.sql)
-- + 12 JobCategories + 24 JobLocations + 120 Jobs (70% APPROVED, 10% PENDING, 10% REJECTED, 10% EXPIRED) + 360 JobSkills
-- =============================================================================

CREATE TABLE IF NOT EXISTS companies (
    id UUID PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    tax_code VARCHAR(13) NOT NULL UNIQUE,
    industry VARCHAR(255),
    size VARCHAR(20),
    address VARCHAR(500),
    city VARCHAR(100),
    website VARCHAR(255),
    logo_url VARCHAR(500),
    description TEXT,
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
    created_by VARCHAR(100),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS job_categories (
    id UUID PRIMARY KEY,
    code VARCHAR(50) NOT NULL UNIQUE,
    name VARCHAR(150) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS job_locations (
    id UUID PRIMARY KEY,
    code VARCHAR(50) NOT NULL UNIQUE,
    city VARCHAR(100) NOT NULL,
    district VARCHAR(150),
    country VARCHAR(100) NOT NULL DEFAULT 'Việt Nam'
);

CREATE TABLE IF NOT EXISTS jobs (
    id UUID PRIMARY KEY,
    company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    category_id UUID REFERENCES job_categories(id),
    location_id UUID REFERENCES job_locations(id),
    title VARCHAR(255) NOT NULL,
    description TEXT NOT NULL,
    requirements TEXT,
    experience_level VARCHAR(30) NOT NULL CHECK (experience_level IN ('FRESHER', 'JUNIOR', 'MIDDLE', 'SENIOR')),
    job_type VARCHAR(30) NOT NULL CHECK (job_type IN ('FULL_TIME', 'PART_TIME', 'INTERNSHIP', 'REMOTE')),
    status VARCHAR(30) NOT NULL CHECK (status IN ('DRAFT', 'PENDING', 'APPROVED', 'REJECTED', 'EXPIRED', 'CLOSED')),
    salary_min NUMERIC(15,2),
    salary_max NUMERIC(15,2),
    work_location VARCHAR(255),
    expires_at TIMESTAMPTZ,
    created_by UUID,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_jobs_company_id ON jobs(company_id);
CREATE INDEX IF NOT EXISTS idx_jobs_status ON jobs(status);

CREATE TABLE IF NOT EXISTS job_skills (
    id UUID PRIMARY KEY,
    job_id UUID NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
    skill_code VARCHAR(50) NOT NULL,
    skill_name VARCHAR(100) NOT NULL,
    min_score INT NOT NULL CHECK (min_score BETWEEN 0 AND 100),
    is_mandatory BOOLEAN NOT NULL DEFAULT TRUE,
    UNIQUE (job_id, skill_code)
);
CREATE INDEX IF NOT EXISTS idx_job_skills_job_id ON job_skills(job_id);

-- 1. 10 Companies
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, industry = EXCLUDED.industry, size = EXCLUDED.size, status = EXCLUDED.status, updated_at = NOW();

-- 2. 12 Job Categories
ON CONFLICT (code) DO NOTHING;

-- 3. 24 Job Locations
ON CONFLICT (code) DO NOTHING;

-- 4. 120 Jobs (84 APPROVED [70%], 12 PENDING [10%], 12 REJECTED [10%], 12 EXPIRED [10%])
ON CONFLICT (id) DO NOTHING;

-- 5. 360 Job Skills
ON CONFLICT (job_id, skill_code) DO NOTHING;
